WITH params AS (SELECT %s::date AS tu_ngay,%s::date AS den_ngay,%s::time AS den_gio,coalesce(%s::text,'') AS ma_kho,coalesce(%s::text,'') AS ma_vt,coalesce(%s::text,'') AS ma_dvcs,%s::integer AS authenticated_user_id,%s::integer AS row_limit),
scope AS (SELECT p.*,u.user_id AS authorized_user_id,coalesce(u.ds_branchs,'') AS ds_branchs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' AS unrestricted FROM params p LEFT JOIN public.userinfo u ON u.user_id=p.authenticated_user_id),
opening AS (SELECT c.ma_vt,sum(c.ton00) so_luong,sum(c.du00) tien FROM public.cdvt c JOIN public.dmkho k ON k.ma_kho=c.ma_kho CROSS JOIN scope s WHERE s.authorized_user_id IS NOT NULL AND c.nam=extract(year FROM s.tu_ngay)::smallint AND (s.ma_kho='' OR c.ma_kho=ANY(string_to_array(s.ma_kho,','))) AND (s.ma_dvcs='' OR k.ma_dvcs=ANY(string_to_array(s.ma_dvcs,','))) AND (s.unrestricted OR k.ma_dvcs=ANY(string_to_array(s.ds_branchs,','))) GROUP BY c.ma_vt UNION ALL SELECT c.ma_vt,sum(c.sl_nhap-c.sl_xuat),sum(c.tien_nhap-c.tien_xuat) FROM public.ct70 c CROSS JOIN scope s WHERE s.authorized_user_id IS NOT NULL AND c.ngay_ct BETWEEN make_date(extract(year FROM s.tu_ngay)::integer,1,1) AND s.tu_ngay-1 AND (s.ma_kho='' OR c.ma_kho=ANY(string_to_array(s.ma_kho,','))) AND (s.ma_vt='' OR c.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.ma_dvcs='' OR c.ma_dvcs2=ANY(string_to_array(s.ma_dvcs,','))) AND (s.unrestricted OR c.ma_dvcs2=ANY(string_to_array(s.ds_branchs,','))) GROUP BY c.ma_vt),
period AS (SELECT c.ma_vt,sum(c.sl_nhap) sl_nhap,sum(c.tien_nhap) tien_nhap,sum(c.sl_xuat) sl_xuat,sum(c.tien_xuat) tien_xuat FROM public.ct70 c CROSS JOIN scope s WHERE s.authorized_user_id IS NOT NULL AND c.ngay_ct+c.time0 BETWEEN s.tu_ngay AND s.den_ngay+s.den_gio AND (s.ma_kho='' OR c.ma_kho=ANY(string_to_array(s.ma_kho,','))) AND (s.ma_vt='' OR c.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.ma_dvcs='' OR c.ma_dvcs2=ANY(string_to_array(s.ma_dvcs,','))) AND (s.unrestricted OR c.ma_dvcs2=ANY(string_to_array(s.ds_branchs,','))) GROUP BY c.ma_vt),
base AS (SELECT coalesce(o.ma_vt,p.ma_vt) ma_vt,sum(coalesce(o.so_luong,0)) ton_dau,sum(coalesce(o.tien,0)) du_dau,sum(coalesce(p.sl_nhap,0)) sl_nhap,sum(coalesce(p.tien_nhap,0)) tien_nhap,sum(coalesce(p.sl_xuat,0)) sl_xuat,sum(coalesce(p.tien_xuat,0)) tien_xuat FROM opening o FULL JOIN period p ON p.ma_vt=o.ma_vt GROUP BY coalesce(o.ma_vt,p.ma_vt))
SELECT row_number() OVER (ORDER BY b.ma_vt) AS stt,b.ma_vt,v.ten_vt,v.ten_vt2,v.dvt,b.ton_dau,b.du_dau,b.sl_nhap,b.tien_nhap,b.sl_xuat,b.tien_xuat,b.ton_dau+b.sl_nhap-b.sl_xuat AS ton_cuoi,b.du_dau+b.tien_nhap-b.tien_xuat AS du_cuoi,count(*) OVER () AS total FROM base b JOIN public.dmvt v ON v.ma_vt=b.ma_vt WHERE abs(b.ton_dau)+abs(b.du_dau)+abs(b.sl_nhap)+abs(b.tien_nhap)+abs(b.sl_xuat)+abs(b.tien_xuat)<>0 ORDER BY b.ma_vt LIMIT (SELECT row_limit FROM params);
